def dedup_triples(triples):
  n = length(triples)
  out = []
  i = 0
  while i < n:
    t = triples[i]
    exists = false
    j = 0
    while j < length(out):
      u = out[j]
      if u.subj == t.subj && u.rel == t.rel && u.obj == t.obj:
        if t.confidence > u.confidence:
          out[j] = t
        exists = true
        j = length(out)
      j = j + 1
    if !exists:
      out = out + [t]
    i = i + 1
  return out

def contains(xs, x):
  i = 0
  n = length(xs)
  while i < n:
    if xs[i] == x:
      return true
    i = i + 1
  return false

def query_knowledge_graph(triples, entity, max_hops):
  if max_hops < 0:
    return []
  if length(triples) == 0:
    return []
  frontier = [entity]
  visited = [entity]
  hop = 0
  results = []
  while hop < max_hops && length(frontier) > 0:
    next_frontier = []
    i = 0
    frontier_len = length(frontier)
    while i < frontier_len:
      e = frontier[i]
      j = 0
      triples_len = length(triples)
      while j < triples_len:
        t = triples[j]
        if t.subj == e:
          results = results + [t]
          if !contains(visited, t.obj):
            visited = visited + [t.obj]
            next_frontier = next_frontier + [t.obj]
        if t.obj == e:
          results = results + [t]
          if !contains(visited, t.subj):
            visited = visited + [t.subj]
            next_frontier = next_frontier + [t.subj]
        j = j + 1
      i = i + 1
    frontier = next_frontier
    hop = hop + 1
  return dedup_triples(results)
