def trustrank(adjacency_list, trusted_seeds, num_iterations, damping_factor):
  if num_iterations < 0:
    return []
  if damping_factor < 0.0 || damping_factor > 1.0:
    return []
  n = length(adjacency_list)
  if n == 0:
    return []
