def take(list, count):
  if count <= 0:
    return []
  n = length(list)
  if count >= n:
    return list
  result = []
  i = 0
  while i < count:
    result = result + [list[i]]
    i = i + 1
  return result

def kmeans_1d(points, k, max_iterations):
  if max_iterations < 0:
    return { centroids: [], assignments: [] }
  n = length(points)
  if n == 0 || k <= 0:
    return { centroids: [], assignments: [] }
  if k > n:
    k = n
  centroids = take(points, k)
  assignments = replicate(n, 0)
  iteration = 0
  epsilon = 0.0001
  while iteration < max_iterations:
    changed = false
    i = 0
    while i < n:
      best_cluster = 0
      best_distance = abs(points[i] - centroids[0])
      c = 1
      while c < k:
        distance = abs(points[i] - centroids[c])
        if distance < best_distance:
          best_distance = distance
          best_cluster = c
        c = c + 1
      if assignments[i] != best_cluster:
        changed = true
        assignments[i] = best_cluster
      i = i + 1
    cluster_sums = replicate(k, 0.0)
    cluster_counts = replicate(k, 0)
    i = 0
    while i < n:
      cluster_index = assignments[i]
      if cluster_index >= 0 && cluster_index < k:
        cluster_sums[cluster_index] = cluster_sums[cluster_index] + points[i]
        cluster_counts[cluster_index] = cluster_counts[cluster_index] + 1
      i = i + 1
    converged = true
    c = 0
    while c < k:
      if cluster_counts[c] > 0:
        new_centroid = cluster_sums[c] / to_f24(cluster_counts[c])
        if abs(new_centroid - centroids[c]) > epsilon:
          converged = false
        centroids[c] = new_centroid
      c = c + 1
    if converged && !changed:
      iteration = max_iterations
    iteration = iteration + 1
  return { centroids: centroids, assignments: assignments }

def cluster_domains_by_authority(domain_scores, num_clusters):
  if num_clusters <= 0:
    return []
  n = length(domain_scores)
  if n == 0:
    return []
  scores = map(domain_scores, fn (domain_score): domain_score.score)
  clustering_result = kmeans_1d(scores, num_clusters, 50)
  output = []
  i = 0
  while i < n:
